package fetcher

import (
	"io"
	"net/http"
	"sync"
)

// FetchAll fetches all URLs concurrently and returns bodies.
func FetchAll(urls []string, client *http.Client) []string {
	results := make([]string, len(urls))
	var wg sync.WaitGroup
	for i, url := range urls {
		go func(idx int, u string) {
			wg.Add(1)         // BUG: Add must be called before go, not inside
			defer wg.Done()
			resp, err := client.Get(u)
			if err != nil {
				return
			}
			// BUG: response body never closed — goroutine/connection leak
			body, _ := io.ReadAll(resp.Body)
			results[idx] = string(body)
		}(i, url)
	}
	wg.Wait()
	return results
}

// FetchOne fetches a single URL and returns the body.
func FetchOne(url string, client *http.Client) (string, error) {
	resp, err := client.Get(url)
	if err != nil {
		return "", err
	}
	// BUG: body never closed
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", err
	}
	return string(body), nil
}

