package fetcher_test

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/ai-verification/goroutine-leak/fetcher"
)

func makeServer(body string) *httptest.Server {
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte(body))
	}))
}

func TestFetchOne(t *testing.T) {
	s := makeServer("hello")
	defer s.Close()
	body, err := fetcher.FetchOne(s.URL, s.Client())
	if err != nil {
		t.Fatal(err)
	}
	if body != "hello" {
		t.Fatalf("expected hello, got %s", body)
	}
}

func TestFetchAll(t *testing.T) {
	s1 := makeServer("first")
	defer s1.Close()
	s2 := makeServer("second")
	defer s2.Close()
	results := fetcher.FetchAll([]string{s1.URL, s2.URL}, http.DefaultClient)
	if len(results) != 2 {
		t.Fatalf("expected 2 results, got %d", len(results))
	}
}

func TestFetchAllEmpty(t *testing.T) {
	results := fetcher.FetchAll(nil, http.DefaultClient)
	if len(results) != 0 {
		t.Fatalf("expected empty, got %d", len(results))
	}
}
